namespace RevLink.Mobile.Views;
public class FeedPage:RevPage {
 public FeedPage():base("Feed"){}
 protected override async Task Load(){Reset("REV / LINK","BUILT FOR CAR CULTURE");Add(Ui.Button("+ NOVA PUBLICAÇÃO",()=>Open(new PostForm())),Ui.Button("Atualizar",Reload,Ui.Surface,Ui.Accent));var items=await Api.Get<List<PostDto>>("/api/posts");if(items.Count==0)Add(Ui.Text("Sem publicações. Seja o primeiro!",15,Ui.Muted));foreach(var p in items){var header=new HorizontalStackLayout{Spacing=10};if(p.DrivatarUrl!=null){var avatar=Ui.Picture(p.DrivatarUrl,42);avatar.WidthRequest=42;header.Children.Add(avatar);}header.Children.Add(Ui.Stack(Ui.Text(p.DriverTag,17,Ui.White,true),Ui.Text(p.CarNickname??"Car spotting",12,Ui.Muted)));var card=Ui.Stack(header,Ui.Picture(p.PhotoUrl,270),Ui.Text(p.Caption),Ui.Text(p.CreatedAt.ToLocalTime().ToString("dd/MM/yyyy HH:mm"),12,Ui.Muted));var like=Ui.Button($"{(p.Liked?"♥":"♡")}  {p.LikeCount} curtidas",async()=>{await Api.Write(p.Liked?HttpMethod.Delete:HttpMethod.Put,$"/api/posts/{p.Id}/like");await Reload();},Ui.Surface,p.Liked?Ui.Accent:Ui.White);card.Children.Add(like);if(p.UserId==Api.Me?.Id)card.Children.Add(Ui.Button("Excluir publicação",async()=>{if(await Confirm("Excluir esta publicação?")){await Api.Write(HttpMethod.Delete,$"/api/posts/{p.Id}");await Reload();}},Ui.Surface,Ui.Danger));Add(Ui.Card(card));}}
}
public class PostForm:FormPage {
 readonly Picker cars=new(){Title="Carro associado (opcional)"};readonly Editor caption=Ui.Editor("Legenda da publicação");List<CarDto> mine=[];bool initialized;
 public PostForm():base("Nova publicação"){var photo=PhotoInput();Add(photo.preview,photo.button,caption,cars,Ui.Button("PUBLICAR",async()=>{int? carId=cars.SelectedIndex>0?mine[cars.SelectedIndex-1].Id:null;await Api.Write(HttpMethod.Post,"/api/posts",new{caption=Ui.Value(caption),carId,photo=photo.data()});await Finish();}));}
 protected override async void OnAppearing(){base.OnAppearing();if(initialized)return;try{mine=await Api.Get<List<CarDto>>("/api/cars/mine");cars.ItemsSource=new[]{"Nenhum / carro visto na rua"}.Concat(mine.Select(x=>x.Nickname)).ToList();cars.SelectedIndex=0;initialized=true;}catch(Exception ex){await DisplayAlertAsync("RevLink",ex.Message,"OK");}}
}
